const API = process.env.LHH_API || "https://discord.com/api/v10";
const IMG = {"introduce-yourself": "", "show-your-kit": "", "staff-guide": "", "my-hospital-keys": "", "maple-shifts": "", "game-ideas": "", "ask-a-real-hero": "", "announcements": "", "welcome": "", "hero-help": "", "rules": "", "pick-your-job": ""};
