let TOKEN = "";
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function api(method, path, body, n = 0) {
  const isForm = body instanceof FormData;
  const r = await fetch(API + path, { method, headers: { Authorization: "Bot " + TOKEN, "User-Agent": "LittleHeroBot (https://be-the-doc.netlify.app, 1.0)", ...(isForm || body === undefined ? {} : { "content-type": "application/json" }) }, body: body === undefined ? undefined : isForm ? body : JSON.stringify(body) });
  if (r.status === 429 && n < 5) { const j = await r.json().catch(() => ({})); await sleep((j.retry_after || 1) * 1000 + 300); return api(method, path, body, n + 1); }
  const t = await r.text(); let j = null; try { j = t ? JSON.parse(t) : null; } catch {}
  if (!r.ok) { const e = new Error(`${r.status} ${(j && j.message) || t.slice(0, 160)}`); e.status = r.status; throw e; }
  await sleep(400); return j;
}
const ok = t => console.log("  ✅ " + t), skip = t => console.log("  ⏭️  " + t), warn = t => console.log("  ⚠️  " + t);
(async () => {
  console.log("\n🦸 Little Hero · channel banners\n");
  const rl = readline.createInterface({ input: stdin, output: stdout });
  let G = String(process.env.LHH_GUILD || process.argv[2] || "").replace(/\D/g, "");
  TOKEN = String(process.env.LHH_TOKEN || "").trim();
  for (let i = 0; !TOKEN && i < 5; i++) TOKEN = (await rl.question("Paste your bot token, then press Enter: ")).trim();
  for (let i = 0; !/^\d{15,22}$/.test(G) && i < 5; i++) G = (await rl.question("Paste your server ID, then press Enter: ")).replace(/\D/g, "");
  rl.close();
  let me;
  try { me = await api("GET", "/users/@me"); } catch (e) { console.log(e.status === 401 ? "That bot token isn't right. Reset it in the Developer Portal and copy it again." : "Couldn't reach Discord: " + e.message); process.exit(1); }
  let chans;
  try { chans = await api("GET", `/guilds/${G}/channels`); } catch { console.log(`The bot isn't in that server. Add it with this link, then run this again:\nhttps://discord.com/oauth2/authorize?client_id=${me.id}&scope=bot%20applications.commands&permissions=8`); process.exit(1); }
  if (me.username !== "Little Hero Bot" || !me.avatar) {
    try { await api("PATCH", "/users/@me", { username: "Little Hero Bot", avatar: ICON }); ok("Bot is now \"Little Hero Bot\" with your logo"); }
    catch (e) { warn("Couldn't change the bot's name or picture yet (" + e.message + "). Set them in the Developer Portal → Bot."); }
  }
  for (const p of POSTS) {
    const ch = chans.find(c => c.name === p.channel && (c.type === 0 || c.type === 5));
    if (!ch) { skip(`#${p.channel}: no channel with that name`); continue; }
    try {
      const recent = await api("GET", `/channels/${ch.id}/messages?limit=50`);
      const mine = recent.filter(m => m.author && m.author.id === me.id);
      if (mine.some(m => (m.attachments || []).some(a => a.filename.startsWith("banner-")))) { skip(`#${p.channel}: already has a banner`); continue; }
      for (const m of mine) { if (!(m.attachments || []).length && !(m.embeds || []).length) await api("DELETE", `/channels/${ch.id}/messages/${m.id}`).catch(() => {}); }
      const fd = new FormData();
      fd.append("payload_json", JSON.stringify({ attachments: [{ id: 0, filename: `banner-${p.banner}.png` }] }));
      fd.append("files[0]", new Blob([Buffer.from(IMG[p.banner], "base64")], { type: "image/png" }), `banner-${p.banner}.png`);
      await api("POST", `/channels/${ch.id}/messages`, fd);
      const msg = await api("POST", `/channels/${ch.id}/messages`, { embeds: [{ color: 0x1F5FAD, title: p.title || undefined, description: p.text, footer: { text: "Little Hero Health" } }], allowed_mentions: { parse: [] } });
      if (p.pin) { try { await api("PUT", `/channels/${ch.id}/messages/pins/${msg.id}`); } catch { await api("PUT", `/channels/${ch.id}/pins/${msg.id}`).catch(() => {}); } }
      ok(`#${p.channel}`);
    } catch (e) { warn(`#${p.channel}: ${e.message}`); }
  }
  console.log(`\n🎉 Done! Open your server to see the banners.\nIf you pasted the rules yourself earlier, you can delete your old copy in #rules.\n`);
})().catch(e => { console.log("\nSomething went wrong: " + e.message); process.exit(1); });
